mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.MSNT_DT DESC) AS LISTNUM, A.TST_UNQ_KY_VAL, A.FRM_ID, E.PRCDOC_NM, E.PRCDOC_NO, B.TITL_NM TEST_NM, C.TITL_NM, C.TH1_ITM_NM, C.TH2_ITM_NM, C.TH3_ITM_NM, C.STDVL_VAL_NM, C.UNIT_NM, A.AGMST_VAL, A.REGPR_ID, A.REGPR_NM, A.RG_DT, A.PAGE_NO, TO_CHAR(A.RG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_RG_DT, TO_CHAR(A.MSNT_DT, 'YYYY-MM-DD HH24:MI:SS') AS FM_MSNT_DT FROM GE_MP_FRMID_S A JOIN GE_MP_CHECK_S B ON A.TST_UNQ_KY_VAL = B.TST_UNQ_KY_VAL
AND B.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
AND B.TITL_NM LIKE '%'||#{SH_TEST_NM}||'%'
JOIN GE_MP_FRMID_M C ON B.FRM_UNQ_KY_VAL = C.FRM_UNQ_KY_VAL AND C.FRM_ID = A.FRM_ID
AND C.FRM_ID = #{FRM_ID}
AND C.TITL_NM LIKE '%'||#{SH_TITL_NM}||'%'
AND (C.TH1_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%' OR C.TH2_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%' OR C.TH3_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%')
JOIN GE_MP_FRM_M D ON C.FRM_UNQ_KY_VAL = D.FRM_UNQ_KY_VAL JOIN GE_MP_PRCDOC_M E ON D.PRCDOC_UNQ_KY_VAL = E.PRCDOC_UNQ_KY_VAL
AND E.PRCDOC_NO LIKE '%'||#{SH_PRCDOC_NO}||'%'
ORDER BY MSNT_DT DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

mapper.update:
UPDATE GE_MP_FRMID_S
   SET AGMST_VAL = #{AGMST_VAL}
 WHERE TST_UNQ_KY_VAL = ${TST_UNQ_KY_VAL}
 AND   FRM_ID =${FRM_ID}

mapper.delete:
DELETE FROM GE_MP_FRMID_S
 WHERE TST_UNQ_KY_VAL = ${TST_UNQ_KY_VAL}
 AND   FRM_ID =${FRM_ID}

DELETE FROM GE_MP_FRMMNT_S
 WHERE TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
 AND   UNQ_ID = #{UNQ_ID}

mapper.update:
UPDATE GE_MP_FRMMNT_S
      SET RG_DT = SYSDATE,
          CHCK_YN = #{CHCK_YN},
          RMK_NM =  #{RMK_NM}
 WHERE UNQ_KY_VAL = ${UNQ_KY_VAL}
